import{_ as t,a,o as i,a6 as d}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Catalog Attribute — Update","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-attribute-update","title":"Update Attribute","description":"Update an attribute. The `code` field cannot be changed. Changing `type` is refused when product attribute values exist. If `options` is supplied, the full set is replaced — existing options keyed by `id` are updated, omitted ids are deleted, and entries without an `id` are inserted.","query":"curl -X PUT \\"https://your-domain.com/api/admin/catalog/attributes/50\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"code\\": \\"material\\",\\n    \\"admin_name\\": \\"Material (updated)\\",\\n    \\"type\\": \\"select\\",\\n    \\"is_filterable\\": true,\\n    \\"translations\\": {\\n      \\"en\\": { \\"name\\": \\"Material (updated)\\" },\\n      \\"fr\\": { \\"name\\": \\"Matière (mis à jour)\\" }\\n    }\\n  }\'\\n","variables":"id=50\\n","response":"{\\n  \\"id\\": 50,\\n  \\"code\\": \\"material\\",\\n  \\"adminName\\": \\"Material (updated)\\",\\n  \\"type\\": \\"select\\"\\n}\\n","commonErrors":[{"error":"Code change refused (422)","cause":"A different `code` was supplied in the payload","solution":"Send the same `code` the attribute was created with — `code` is immutable"},{"error":"Type immutable (422)","cause":"`type` change attempted while product attribute values exist","solution":"Delete dependent product attribute values first, or do not change `type`"},{"error":"Not Found (404)","cause":"The attribute id does not exist","solution":"Verify the id via the listing endpoint"},{"error":"Unauthorized (401)","cause":"Missing or invalid admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/attributes/attributes-update.md","filePath":"api/rest-api/admin/catalog/attributes/attributes-update.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/attributes/attributes-update.md"};function o(n,e,s,l,u,c){return i(),a("div",null,e[0]||(e[0]=[d('<h1 id="catalog-attribute-—-update" tabindex="-1">Catalog Attribute — Update <a class="header-anchor" href="#catalog-attribute-—-update" aria-label="Permalink to &quot;Catalog Attribute — Update&quot;">​</a></h1><p>Updates an existing attribute. Mirrors <strong>Catalog → Attributes → Edit</strong> in the Bagisto admin panel.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/attributes/{id}</code></td><td>PUT</td></tr></tbody></table><p><code>{id}</code> must be a positive integer (<code>requirements: [&#39;id&#39; =&gt; &#39;\\\\d+&#39;]</code>).</p><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><p>Same fields as <a href="/api/rest-api/admin/catalog/attributes/attributes-create.html">Create</a>, with these rules:</p><ul><li><strong><code>code</code> is immutable.</strong> Sending a different code returns <code>422</code>.</li><li><strong><code>type</code> cannot be changed</strong> if any product attribute value references this attribute. Returns <code>422</code>.</li><li><strong><code>options</code> is a full-set replacement.</strong> Entries with an <code>id</code> are updated, entries without <code>id</code> are inserted, and any existing option ids omitted from the payload are deleted.</li><li>System attributes (<code>is_user_defined = 0</code>) silently ignore immutable fields by convention — only mutable fields (e.g. <code>admin_name</code>, translations) are applied.</li><li><code>translations</code> merges per-locale — only the supplied locales are updated; others are untouched.</li></ul><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code> returning the full attribute detail — identical shape to <a href="/api/rest-api/admin/catalog/attributes/attributes-detail.html"><code>GET /api/admin/catalog/attributes/{id}</code></a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>The attribute does not exist</td></tr><tr><td><code>422 Unprocessable Entity</code></td><td>Code change attempted, type change refused, or other validation failure</td></tr></tbody></table>',12)]))}const b=t(r,[["render",o]]);export{h as __pageData,b as default};
